+
+	ret = vcnl4040_update_als_int(data, VCNL4040_ALS_CONF_INT_EN, false);
+	if (ret < 0)
+		return ret;
+
+	ret = i2c_smbus_read_word_data(data->client, data->chip_spec->int_reg);
+	if (ret < 0)
+		return ret;
+
+	return 0;
+}
