> > static void teardown_sockets(int *fds, unsigned int count)
> > {
> >         unsigned int i;
> >
> >         if (!fds)
> >                 return;
> >
> >         for (i = 0; i < count; i++) {
> >                 if (fds[i] >= 0)
> >                         close(fds[i]);
> >         }
> >         free(fds);
> > }
