> > static int parse_u32(const char *arg, unsigned int *value)
> > {
> >         char *end = NULL;
> >         unsigned long parsed;
> >
> >         parsed = strtoul(arg, &end, 0);
> >         if (!end || *end || parsed > UINT32_MAX)
> >                 return -1;
> >
> >         *value = (unsigned int)parsed;
