-static int vd55g1_poll_reg(struct vd55g1 *sensor, u32 reg, u8 poll_val,
-			   int *err)
-{
-	unsigned int val = 0;
-	int ret;
-
-	if (err && *err)
-		return *err;
-
-	ret = regmap_read_poll_timeout(sensor->regmap, CCI_REG_ADDR(reg), val,
-				       (val == poll_val), 2000,
-				       500 * USEC_PER_MSEC);
-
-	if (ret && err)
-		*err = ret;
-
-	return ret;
-}
